const uploads = $('Upload').all();
const chunkMeta = $('Expand Audio Chunks').all();
if (!uploads.length) {
  throw new Error('No uploaded audio chunks');
}
if (chunkMeta.length && chunkMeta.length !== uploads.length) {
  throw new Error(`Chunk/upload count mismatch: ${chunkMeta.length} chunks vs ${uploads.length} uploads`);
}

return uploads.map((item, index) => {
  const meta = chunkMeta[index] ? chunkMeta[index].json : {};
  return {
    json: {
      // Global order across all files (used for wait/skip-last + stitch order)
      chunkIndex: index,
      chunkCount: uploads.length,
      // Per-file identity from backend listMeetingChunks
      fileIndex: meta.fileIndex ?? 0,
      fileCount: meta.fileCount ?? 1,
      audioFileId: meta.audioFileId || null,
      fileChunkIndex: meta.chunkIndex ?? index,
      fileChunkCount: meta.chunkCount ?? uploads.length,
      mimeType: item.json.file.mimeType,
      fileUri: item.json.file.uri
    }
  };
});

