const chunks = $input.first().json.chunks || [];
if (!chunks.length) {
  throw new Error('No audio chunks to transcribe');
}

return chunks.map((chunk) => ({ json: chunk }));

function stitchTranscripts(parts) {
  let result = '';
  for (const part of parts) {
    const text = String(part || '').trim();
    if (!text) continue;
    if (!result) {
      result = text;
      continue;
    }
    const prevWords = result.split(/\s+/).slice(-12).join(' ');
    const windowText = text.slice(0, 1200);
    const at = prevWords ? windowText.indexOf(prevWords) : -1;
    if (at >= 0) {
      const remainder = text.slice(at + prevWords.length).trim();
      result = remainder ? result.trimEnd() + '\n\n' + remainder : result;
    } else {
      result = result.trimEnd() + '\n\n' + text;
    }
  }
  return result.trim();
}

const responses = $('TranscribeAudio').all();
const parts = responses.map((item) => {
  const text = item.json?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) {
    throw new Error('A transcription chunk did not return text');
  }
  return text;
});

return [{ json: { text: stitchTranscripts(parts) } }];
